package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;

class EntityHeatSnapshotTest {
    final Instant first=Instant.parse("2026-01-01T08:00:00.000001Z");
    EntityHeatSnapshot value(String id,long count){return new EntityHeatSnapshot(id,"news_tech",3,count,"Fictional title","Fictional summary",first,LocalDate.of(2026,1,1),false);}
    @Test void ExactCanonicalFactsRoundTripAndNullLegacyFactsStayUnknown(){var value=value("fictional-entity",7);assertEquals(value,EntityHeatSnapshot.read(value.json()));assertEquals(value.hash(),EntityHeatSnapshot.read(value.json()).hash());var unknown=new EntityHeatSnapshot("fictional-legacy","news_tech",0,null,null,null,null,null,true);assertNull(EntityHeatSnapshot.read(unknown.json()).occurrenceCount());assertTrue(EntityHeatSnapshot.read(unknown.json()).legacy());assertNotEquals(value.hash(),value("fictional-entity",8).hash());assertFalse(value.toString().contains("Fictional"));}
    @Test void SplitsRequireBothActualTouchedEntitiesAndKeepStableImmutableOrdering(){var old=value("fictional-old",2);var next=value("fictional-new",1);var complete=EntityHeatSnapshot.completeTouched(List.of(old,next),old.entityId(),next.entityId());assertEquals(List.of(next,old),complete);assertThrows(UnsupportedOperationException.class,()->complete.clear());assertThrows(RuntimeException.class,()->EntityHeatSnapshot.completeTouched(List.of(next),old.entityId(),next.entityId()));assertThrows(RuntimeException.class,()->EntityHeatSnapshot.completeTouched(List.of(old,old),old.entityId(),next.entityId()));assertTrue(EntityHeatSnapshot.completeTouched(List.of(),null,null).isEmpty());assertEquals(List.of(old),EntityHeatSnapshot.completeTouched(List.of(old),old.entityId(),null));assertThrows(RuntimeException.class,()->EntityHeatSnapshot.completeTouched(List.of(old),null,null));}
    @Test void ClosedSchemaRejectsUnknownRolesUnsafeCountAndNonUtcTime(){var n=(ObjectNode)value("fictional-entity",7).toJson();n.put("native_verified",true);assertThrows(RuntimeException.class,()->EntityHeatSnapshot.read(new String(CanonicalJson.bytes(n),java.nio.charset.StandardCharsets.UTF_8)));n.remove("native_verified");n.put("occurrence_count",-1);assertThrows(RuntimeException.class,()->EntityHeatSnapshot.read(new String(CanonicalJson.bytes(n),java.nio.charset.StandardCharsets.UTF_8)));n.put("occurrence_count",7);n.put("first_recorded_at","2026-01-01T16:00:00.000001+08:00");assertThrows(RuntimeException.class,()->EntityHeatSnapshot.read(new String(CanonicalJson.bytes(n),java.nio.charset.StandardCharsets.UTF_8)));assertThrows(RuntimeException.class,()->value("fictional-entity",CanonicalJson.MAX_SAFE_INTEGER+1));assertThrows(RuntimeException.class,()->new EntityHeatSnapshot("fictional-entity","news_tech",0,1L,"Fictional",null,first.plusNanos(1),null,false));}
    @Test void NativeTextAndPhysicalBudgetsNeverTruncateOrRepairFacts(){assertThrows(RuntimeException.class,()->new EntityHeatSnapshot("fictional-entity","news_tech",0,1L,"F".repeat(513),null,first,null,false));assertThrows(RuntimeException.class,()->new EntityHeatSnapshot("fictional-entity","news_tech",0,1L,"Fictional","F".repeat(EntityHeatSnapshot.MAX_TEXT_BYTES),first,null,false));assertThrows(RuntimeException.class,()->new EntityHeatSnapshot("fictional-entity","news_tech",0,1L,"Fictional","\ud800",first,null,false));assertThrows(RuntimeException.class,()->EntityHeatSnapshot.read(" ".repeat(EntityHeatSnapshot.MAX_PHYSICAL_BYTES+1)));assertThrows(RuntimeException.class,()->new EntityHeatSnapshot("fictional-entity","news_tech",0,1L,"Fictional",null,first,LocalDate.of(2026,1,2),false));}
}
